import heapq
class Solution:
    def findMaxSum(self, nums1: List[int], nums2: List[int], k: int) -> List[int]:
        n = len(nums1)
        order = sorted(range(n), key=lambda i: nums1[i])
        ans = [0] * n
        h, s = [], 0
        i = 0
        while i < n:
            j = i
            while j < n and nums1[order[j]] == nums1[order[i]]:
                j += 1
            for t in range(i, j):
                ans[order[t]] = s
            for t in range(i, j):
                heapq.heappush(h, nums2[order[t]])
                s += nums2[order[t]]
                if len(h) > k:
                    s -= heapq.heappop(h)
            i = j
        return ans

