class Solution {
public:
    vector<long long> findMaxSum(vector<int>& nums1, vector<int>& nums2, int k) {
        int n = nums1.size();
        vector<int> ord(n);
        iota(ord.begin(), ord.end(), 0);
        sort(ord.begin(), ord.end(), [&](int a, int b){ return nums1[a] < nums1[b]; });
        vector<long long> ans(n);
        priority_queue<int, vector<int>, greater<int>> pq;
        long long s = 0;
        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && nums1[ord[j]] == nums1[ord[i]]) j++;
            for (int t = i; t < j; t++) ans[ord[t]] = s;
            for (int t = i; t < j; t++) {
                pq.push(nums2[ord[t]]); s += nums2[ord[t]];
                if ((int)pq.size() > k) { s -= pq.top(); pq.pop(); }
            }
            i = j;
        }
        return ans;
    }
};

