class Solution {
    public long[] findMaxSum(int[] nums1, int[] nums2, int k) {
        int n = nums1.length;
        Integer[] ord = new Integer[n];
        for (int i = 0; i < n; i++) ord[i] = i;
        Arrays.sort(ord, (a, b) -> Integer.compare(nums1[a], nums1[b]));
        long[] ans = new long[n];
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        long s = 0;
        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && nums1[ord[j]].equals(nums1[ord[i]])) j++;
            for (int t = i; t < j; t++) ans[ord[t]] = s;
            for (int t = i; t < j; t++) {
                pq.offer(nums2[ord[t]]); s += nums2[ord[t]];
                if (pq.size() > k) s -= pq.poll();
            }
            i = j;
        }
        return ans;
    }
}

