var findMaxSum = function(nums1, nums2, k) {
    const n = nums1.length;
    const ord = [...Array(n).keys()].sort((a, b) => nums1[a] - nums1[b]);
    const ans = new Array(n).fill(0);
    const h = [];
    let s = 0;
    const push = v => { h.push(v); let i = h.length - 1; while (i > 0) { const p = (i - 1) >> 1; if (h[p] <= h[i]) break; [h[p], h[i]] = [h[i], h[p]]; i = p; } };
    const pop = () => { const t = h[0]; h[0] = h[h.length - 1]; h.pop(); let i = 0; for (;;) { let m = i; if (2*i+1 < h.length && h[2*i+1] < h[m]) m = 2*i+1; if (2*i+2 < h.length && h[2*i+2] < h[m]) m = 2*i+2; if (m === i) break; [h[m], h[i]] = [h[i], h[m]]; i = m; } return t; };
    let i = 0;
    while (i < n) {
        let j = i;
        while (j < n && nums1[ord[j]] === nums1[ord[i]]) j++;
        for (let t = i; t < j; t++) ans[ord[t]] = s;
        for (let t = i; t < j; t++) { push(nums2[ord[t]]); s += nums2[ord[t]]; if (h.length > k) s -= pop(); }
        i = j;
    }
    return ans;
};
